(window.webpackJsonp=window.webpackJsonp||[]).push([[96],{467:function(t,v,_){"use strict";_.r(v);var e=_(11),n=Object(e.a)({},(function(){var t=this,v=t._self._c;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("h3",{attrs:{id:"原文"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#原文"}},[t._v("#")]),t._v(" 原文")]),t._v(" "),v("p",[v("font",{attrs:{color:"#c00000",size:"5px"}},[v("center",[t._v("我有三宝")])],1),t._v("\n天下皆谓我道大，似不肖[1]。夫唯大，故似不肖。若肖，久矣其细也夫！我有三宝，持而保之：一曰慈[2]，二曰俭[3]，三曰不敢为天下先。慈，故能勇；俭，故能广[4]；不敢为天下先，故能成器长[5]。今舍慈且勇[6]，舍俭且广，舍后且先，死矣。夫慈，以战则胜，以守则固。天将救之，以慈卫之。")],1),t._v(" "),v("br"),t._v(" "),v("Badge",{attrs:{text:"注释",type:"warning"}}),t._v(" "),v("p",[t._v("[1]似不肖：意思是不像任何具体的事物，即已大到无形。肖，即相像之义。")]),t._v(" "),v("p",[t._v("[2]慈：慈爱。")]),t._v(" "),v("p",[t._v("[3]俭：这里指俭啬，即节约精神、爱惜精力。")]),t._v(" "),v("p",[t._v("[4]广：宽广，生命能够更宏阔，做出更大的事业。")]),t._v(" "),v("p",[t._v("[5]器长：万物的首领。器，指物。长，首领。")]),t._v(" "),v("p",[t._v("[6]舍慈且勇：舍弃慈爱而妄逞勇武。且，选取。\n　　\n"),v("Badge",{attrs:{text:"译文",type:"warning"}}),t._v("\n　\n天下人都说我的“道”大，看上去和任何具体的事物都不像。正因为它很大，所以才不像任何具体的事物。如果它像某一样具体的事物，那么它也就变成了微不足道、不值一提的东西了。我认为，有三件宝贝是应当永远保持的：第一件叫作慈爱，第二件叫作俭啬，还有一件事不敢居于天下人的前面。慈爱则视人民如赤子而尽力卫护，所以能产生勇气；俭啬则能蓄精积德，应用无穷，所以使生命活得更为宽广；不敢居于天下人的前面，乃是一种谦卑，这样便能够受到人们的尊敬和拥护，成为人们的首领。但是如果舍弃慈爱而妄逞勇武，舍弃俭啬而贪图功名，舍弃退让而争先，那是走向死亡的道路。在这三个宝贝之中，慈爱最重要，以慈爱之心用于战争就会取得胜利，用来防守就能巩固。能够发挥慈爱之心的人，天也会来救助他、卫护他。")],1),t._v(" "),v("Badge",{attrs:{text:"阅读感悟",type:"warning"}}),t._v(" "),v("p",[t._v("连接、边界、半满存在动态平衡")]),t._v(" "),v("br"),t._v(" "),v("hr"),t._v(" "),v("div",{staticClass:"center-container"},[v("p",[t._v("📢 "),v("code",[t._v("版权声明")]),t._v("：本文为原创文章，著作权归 "),v("code",[t._v("【赵敏】")]),t._v(" 所有。"),v("br"),t._v("\n个人学习、研究可自由转载，但必须注明出处；"),v("code",[t._v("商业用途必须获得书面授权")]),t._v("，侵权必究。")])]),v("br")],1)}),[],!1,null,null,null);v.default=n.exports}}]);